(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["bs"] = {"ui":{"skip":"Preskoči na sadržaj","back":"← Nazad na AI-gile","lang.button":"Jezik: {name}","lang.dialog":"Odaberi jezik","lang.search":"Traži jezike","lang.none":"Nijedan jezik ne odgovara","lang.notYet":"{name} još nije preveden","theme.aria":"Prebaci između svijetle i tamne teme","theme.toLight":"Prebaci na svijetlu temu","theme.toDark":"Prebaci na tamnu temu","index.title":"AI-gile: tvoj AI razvojni tim, na jednoj tabli","index.description":"AI-gile je kanban tabla za AI timove koji programiraju. Rade dok ti spavaš; ti dobiješ jednu kratku hrpu stvari za odluku, testiranje i prihvatanje.","hero.logoAlt":"Ikona AI-gile table","hero.h1.html":"Tvoj AI razvojni tim, na jednoj&nbsp;tabli.","hero.alpha":"🐣 Zatvorena pre-alfa","hero.alphaTitle":"Rano i nedovršeno: hvala što isprobavaš!","hero.lede":"Grade dok ti spavaš. Probudiš se uz jednu kratku hrpu: nekoliko pitanja, nekoliko stvari za testiranje, jedan ili dva ljubičasta dijamanta. Klik, prihvaćeno, nazad na kafu.","dl.windows":"Windows aplikacija","dl.browser":"Pokreni u pregledniku","dl.soon":"Uskoro","dl.notify":"🔔 Javi mi kad se otvori","dl.notifySmall":"Alfa ili beta","hero.secondary":"Agile, ali tim nikad ne treba kafu uz stand-up. (Stand-up ipak održavaju.)","pitch.h2":"AI-gile u onoliko riječi koliko želiš","pitch.lede":"Odaberi dužinu, od jedne riječi do 144. Svaka dužina je poseban opis, napisan baš za tu veličinu. Povuci klizač ili koristi tipke sa strelicama.","pitch.rangeLabel":"Dužina u riječima","pitch.dice":"🎲 druga verzija","pitch.words.one":"{n} riječ","pitch.words.few":"{n} riječi","pitch.words.other":"{n} riječi","pitch.letters.one":"{n} slovo","pitch.letters.few":"{n} slova","pitch.letters.other":"{n} slova","pitch.chars.one":"{n} znak","pitch.chars.few":"{n} znaka","pitch.chars.other":"{n} znakova","count.line.html.one":"{n} kartica na tabli upravo sada","count.line.html.few":"{n} kartice na tabli upravo sada","count.line.html.other":"{n} kartica na tabli upravo sada","features.aria":"Šta radi","f.pile.h":"Jedna hrpa za tebe","f.pile.html":"<b>Za tebe</b> okuplja sve što čeka na tebe, kroz sve projekte: pitanja, stvari za testiranje, zadatke koje može uraditi samo čovjek. Tvoj red kaže šta je sljedeće i koliko traje.","f.sleep.h":"Timovi koji rade dok ti spavaš","f.sleep.p":"Svaki projekt ima lead i tim AI agenata. Komentariši karticu i tim se budi, odradi posao i vrati ti ga s koracima koje može pratiti i umoran čovjek.","f.tester.h":"Prvo provjerava AI tester","f.tester.p":"Prije nego išta stigne do tebe, tester prođe korake u kopiji aplikacije i pokaže šta je vidio, sa snimkom ekrana. Prelistaj one koje su prošle i prihvati jednim klikom.","f.proof.h":"Dokazi, a ne obećanja","f.proof.p":"Svaka predaja pokazuje šta se promijenilo: datoteke, razlike, snimke ekrana. Ne moraš otvarati svaku aplikaciju da vidiš je li gotovo.","f.chat.h":"Čavrljaj sa svojim leadovima","f.chat.p":"Traka u stilu Discorda: jedna ikona po projektu, ljubičasti dijamanti za ono što treba tebe. Pošalji leadu ideju; pretvorit će je u kartice i plan, uz dugme ✅ Go.","f.tidy.h":"Sam održava red","f.tidy.p":"Srodne kartice se spajaju u jednu, zbrkani naslovi se popravljaju, a provjera tokena drži kod vitkim. Manje stvari između kojih prebacuješ, manje razmišljanja.","f.private.h":"Tvoje, na tvom računaru","f.private.li1":"Tabla radi na tvom vlastitom računaru i odgovara samo tebi.","f.private.li2":"Privatne poruke među ljudima su šifrovane od kraja do kraja.","f.private.li3":"Bez računa, bez trackera, bez kolačića.","f.lang.h":"Na tvom jeziku","f.lang.p":"Preko 120 jezika, od holandskog, velškog i japanskog do gusarskog, Yode i klingonskog, uz brzo prebacivanje na engleski za programerske riječi.","tl.aria":"Vremenska crta od prvog razgovora do plana razvoja","tl.h2":"Od prvog četa do onoga što slijedi","tl.lede":"Pravi datumi i vremena, u tvojoj vremenskoj zoni. Poslije danas je plan, bez obećanih datuma.","tl.today":"Danas","tl.planned":"planirano","tl.cards.one":"{n} kartica","tl.cards.few":"{n} kartice","tl.cards.other":"{n} kartica","join.h2":"Pridruži se","join.lede":"AI-gile gradi jedan mali čovjek i veliki broj strpljivih agenata. Za sada je privatan, u zatvorenoj alfi s prijateljima. Želiš li probati kad se otvori?","join.btn":"Prijavi interes","join.small":"Poslat ćemo ti e-mail, ništa drugo","footer.tag":"AI-gile. Bez trackera, bez kolačića, bez kafe uz stand-up.","footer.licence":"Poslovna licenca","footer.status":"Status","form.sending":"Šaljem…","form.failed":"Nije uspjelo: pokušaj ponovo kasnije.","form.offline":"Nije moguće doći do AI-gile: pokušaj ponovo kasnije.","interest.title":"AI-gile: javi mi kad se otvori alfa","interest.description":"Ostavi e-mail da saznaš kad se otvori zatvorena alfa ili beta AI-gile.","interest.h1":"🔔 Javi mi kad se otvori","interest.lede":"AI-gile je u zatvorenoj pre-alfi. Ostavi e-mail i javit ćemo ti se jednom, kad bude mjesta za tebe.","interest.email":"Tvoj e-mail","interest.which":"Koje testiranje?","interest.alpha":"Zatvorena alfa: rano, grubo, mnogo promjena","interest.beta":"Beta: stabilnija, kasnije","interest.both":"Bilo koje, šta prije stigne","interest.submit":"Stavi me na listu","interest.thanks":"Hvala! Na listi si.","licence.title":"AI-gile: poslovna licenca","licence.description":"Koristiš li AI-gile u svom poslu? Zatraži besplatnu poslovnu licencu.","licence.h1":"📜 Poslovna licenca","licence.lede":"Koristiš li AI-gile na poslu? Reci nam ko si i čime se baviš. Ako čini nešto dobro, licenca je besplatna.","licence.company":"Firma","licence.website":"Web stranica","licence.what":"Čime se baviš","licence.how":"Kako pomaže svijetu","licence.email":"E-mail","licence.submit":"Prijavi se","licence.thanks":"Hvala! Odgovorit ćemo e-mailom.","status.title":"AI-gile status","status.h1":"AI-gile status","status.quiet":"Sve mirno","status.checking":"Provjeravam…","status.offline":"Trenutno nije moguće doći do servisa statusa (pokušavam ponovo)","status.updated":"ažurirano {ago}","status.justNow":"upravo sada","status.min":"prije {n} min","status.hours":"prije {n} h","status.days":"prije {n} d","live.h2":"Gledajte kako se gradi, uživo","live.caption":"Svaka kartica je skrivena: vidite oblik posla, a ne riječi.","live.watching.one":"uživo: {n} gleda","live.watching.other":"uživo: {n} gleda","live.offline":"Tabla uživo malo odmara. Navratite uskoro.","live.cols":"Backlog|Za uraditi|U toku|Tim provjerava|Za tvoje testiranje|Za tim|Gotovo","live.last.now":"Posljednja kartica premještena je upravo sada","live.last.min.one":"Posljednja kartica premještena je prije {n} min","live.last.min.other":"Posljednja kartica premještena je prije {n} min","live.last.hour.one":"Posljednja kartica premještena je prije {n} sat","live.last.hour.other":"Posljednja kartica premještena je prije {n} sati","live.last.day.one":"Posljednja kartica premještena je prije {n} dan","live.last.day.other":"Posljednja kartica premještena je prije {n} dana"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboti.","Delegirano."]},{"n":2,"texts":["Robotski kanban.","Agenti, organizovano.","Ideje, izgrađene."]},{"n":3,"texts":["Kanban za robote.","Ideje postaju funkcije.","Besplatni agentski kanban."]},{"n":5,"texts":["Kanban tabla koju vode agenti.","Ti pišeš kartice. Agenti grade.","Besplatno, lokalno, testirano, pomalo smiješno."]},{"n":8,"texts":["Besplatna kanban tabla na kojoj rade AI agenti.","Napiši ideju. Agenti je grade. Ti prihvataš.","Agile za jednog čovjeka i mnogo strpljivih robota."]},{"n":13,"texts":["Kanban tabla na tvom računaru na kojoj AI agenti preuzimaju kartice.","Napiši ideju. Tim agenata je izgradi, zatim je tester provjeri, a ti kažeš da.","Besplatno, bez računa, bez trackera: tabla, nekoliko robota i ti kao šef."]},{"n":21,"texts":["AI-gile je kanban tabla za rad s AI agentima koji programiraju. Oni preuzimaju kartice; ti ih testiraš i prihvataš.","Svaki projekt dobije lead i tim AI agenata. Komentariši bilo koju karticu i tim odmah prione na posao.","Besplatna, lična tabla zadataka koja radi na tvom vlastitom računaru. Radnici su roboti. Onaj ko kaže da, to si ti."]},{"n":34,"texts":["Ideje stavljaš na tablu. Tim AI agenata ih pretvara u funkcije koje rade, testira ih i vraća ti ih s koracima za isprobavanje. Ništa se ne računa kao gotovo dok ti to ne kažeš.","AI-gile je domaća kanban tabla koju je Rich napravio uz mnogo pomoći agenata kojima sada upravlja. Besplatna je, radi na tvom računaru i dijeli se s prijateljima, ne prodaje se.","Zamisli običnu kanban tablu, s kolonama od Backloga do Gotovo, samo što kartice preuzimaju AI agenti. Javljaju napredak, pitaju kad zapnu i uvijek čekaju tvoj podignuti palac."]},{"n":55,"texts":["AI-gile je kanban tabla na kojoj tim čine AI agenti. Svaki projekt ima lead koji planira posao i pomoćnike koji ga grade. Kad je funkcija spremna, AI tester je isproba i napravi snimak ekrana, a onda sleti na tvoju hrpu. Prihvati je ili napiši komentar pa je prerade.","Počelo je kao način na koji je jedna osoba pratila mnogo AI programerskih sesija odjednom, a izraslo je u pravu tablu. Radi na tvom računaru, ne traži račun i nema trackera. Besplatna je za prijatelje i znatiželjnike. Također je nedovršena, pa računaj na grube ivice i poneko iznenađenje.","Evo poštene verzije. Ideje i dalje moraš imati ti, a rezultate i dalje moraš provjeriti ti. AI-gile radi sve između: drži kartice u redu, budi pravog agenta kad komentarišeš, pokazuje tačno šta se promijenilo i sve to slaže u jednu kratku hrpu za tebe."]},{"n":89,"texts":["AI-gile je besplatna kanban tabla koju pokrećeš na vlastitom računaru. Umjesto ljudi, svaki projekt ima tim AI agenata: lead koji tvoje ideje pretvara u kartice i plan, i pomoćnike koji kartice preuzimaju po prioritetu. Kad je nešto izgrađeno, AI tester slijedi korake testiranja i pokazuje ti šta je vidio. Zatim čeka u jednoj hrpi koja se zove Za tebe. Ti je prihvatiš, ili komentarišeš pa tim pokuša ponovo. Ništa ne stiže do Gotovo bez tebe.","Nekoliko stvari koje možda ne očekuješ. Noćna straža drži kolonu Za uraditi popunjenom dok ti spavaš, birajući kartice kojima ne treba tvoj odgovor. Brojač tokena pokazuje koliko su agenti potrošili danas i ove sedmice, a No Token Mode im kaže da prestanu trošiti. Možeš pisati prijateljima, a privatne poruke su šifrovane od kraja do kraja. Tabla govori oko 120 jezika, uključujući holandski, flamanski, gusarski i klingonski. Ništa od toga ne košta ni feninga, a niko ti to ni ne pokušava prodati.","AI-gile je mali, lični projekt, a ne firma. Rich je htio voditi nekoliko AI programerskih projekata bez otvaranja svake aplikacije da ih provjeri, pa su on i agenti napravili tablu za to, a onda tablu iskoristili da izgrade ostatak sebe. U zatvorenoj je pre-alfi, što znači da radi, uglavnom, za šaku prijatelja. Nema stranice s cijenama, nema newslettera i nema plana rasta. Ako ti zvuči korisno, možeš zatražiti da probaš kad se malo više otvori."]},{"n":144,"texts":["AI-gile je kanban tabla za jednog čovjeka i mnogo AI agenata. Radi na tvom vlastitom računaru i potpuno je besplatna. Dodaješ projekte, a svaki projekt dobije lead i mali tim. Čavrljaš s leadom, pomalo kao na Discordu, i opišeš ideju; lead je pretvara u kartice i plan, pa čeka da pritisneš Go. Tim kartice rješava po prioritetu, koristeći jednostavnu komandnu liniju napravljenu za jezičke modele. Prije nego se išta vrati tebi, AI tester prođe korake u kopiji aplikacije i priloži snimak ekrana. Gotov posao sleti na tvoju hrpu s promijenjenim datotekama i razlikom. Ti ga prihvatiš, ili ostaviš komentar pa se tim probudi i pokuša ponovo. Samo ti možeš premjestiti karticu u Gotovo. Nema računa, nema trackera i nema kolačića, a sve ostaje na tvom računaru.","Otprilike jedan dan s AI-gile. Navečer ostaviš nekoliko komentara: ovo dugme je na pogrešnom mjestu, ta lista bi trebala biti sortirana, može li tamni mod. Odeš spavati. Agenti pročitaju komentare, naprave izmjene, testiraju ih i vrate ti ih. Ako Za uraditi ostane prazno, noćna straža ga puni iz backloga karticama kojima ne treba tvoj odgovor. Ujutro te čeka jedna kratka hrpa: par pitanja i nekoliko stvari za isprobavanje, svaka s koracima koje može slijediti i pospana osoba i sa snimkom ekrana na kojem radi. Prokliktaš se, prihvatiš dobre, a ostale vratiš. Brojač tokena pokazuje šta je sve to potrošilo, a No Token Mode je tu za štedljive sedmice. Onda doručkuješ, a u tome ti agenti još ne mogu pomoći.","Prvo, šta AI-gile nije. Nije startup, nije na prodaju i niko ne prikuplja tvoje podatke. To je besplatna tabla koja radi na tvom računaru, bez računa, bez trackera i bez kolačića. A šta jeste: jedno uredno mjesto na kojem vidiš sve AI programerske projekte odjednom, s timom agenata koji radi kartice i tobom koji donosiš odluke. Spaja srodne kartice, popravlja zbrkane naslove i pazi koliko kod ostaje vitak. Govori oko 120 jezika, od holandskog i flamanskog do gusarskog i klingonskog. Prijatelji mogu pisati jedni drugima, privatno i šifrovano. Napravili su je Rich i veliki broj strpljivih agenata, uglavnom koristeći nju samu. U zatvorenoj je pre-alfi, pa je na mjestima gruba. Ako ti zvuči zabavno, lijepo pitaj i možda uđeš ranije."]}],"quips":{"1":"Jedna riječ. Hrabro. Možda i previše hrabro.","3":"Tri riječi. Već iskrenije od većine stranica proizvoda.","8":"Osam riječi. I dalje kraće od stand-upa.","21":"Dužine su, usput, story pointi. Naravno da jesu.","55":"Pedeset pet riječi. Dvije kartice su završene dok si čitao.","144":"To je ona duga. Nema 233. Agenti su otišli spavati."}},"timeline":{"first-idea.name":"Prva ideja","first-idea.line":"Sasvim prvi razgovor, prije nego što je postojao ijedan red koda.","first-board.name":"Prva tabla","first-board.line":"Tabla koja prati vlastitu izgradnju: kartice, kolone, prevlačenje, projekti.","team-roles.name":"Tim i uloge","team-roles.line":"Profili agenata, šabloni timova, prostori i ko šta radi.","install.name":"Instalacija i izdanja","install.line":"Zip koji prijatelj može instalirati, samoažuriranje, kanali i vraćanje unazad.","usage-saver.name":"Štednja potrošnje","usage-saver.line":"Mjeri koliko koštaju pokretanja, drži kod vitkim, čuvaj svoj limit.","friends.name":"Prijatelji i dijeljenje","friends.line":"Privatne poruke, šifrovani relej, pozivnice, uloge i zajednički projekti.","languages.name":"Jezici","languages.line":"Svaki tekst na ekranu u jezičkoj datoteci, prvo holandski i flamanski.","ai-tester.name":"AI tester","ai-tester.line":"Tester prvi provjerava svaku predaju i pokazuje šta je vidio.","website.name":"Web stranica","website.line":"aigile.lol, teaser i ova vremenska crta.","streaming.name":"Čet i striming","streaming.line":"Discord, Twitch, OBS, streamerski mod, GIF-ovi i emotikoni.","no-ai.name":"Izdanje bez AI-ja","no-ai.line":"Tabla za ljude koji programiraju bez AI-ja, i javne table.","night-watch.name":"Noćna straža","night-watch.line":"Čuvar i Scrum Master drže timove na zadatku dok ti spavaš.","p-more.name":"Sve ostalo","p-more.line":"Manje ideje koje još čekaju svoj red.","p-android.name":"Telefon i Android","p-android.line":"Do svoje table s telefona, a zatim izvorna Android aplikacija.","p-release.name":"Alfa i dalje","p-release.line":"Zatvorena alfa, živa stranica, pa beta.","p-languages.name":"Više jezika","p-languages.line":"Više od stotinu jezika i mod uronjenosti za one koji uče.","p-engines.name":"Više AI motora","p-engines.line":"Odaberi Claude, Codex ili Gemini za svakog agenta.","p-pro.name":"Profesionalna praksa","p-pro.line":"Oznake rizika, kapije za spajanje, kartice incidenata i zaštitne ograde.","p-self.name":"Briga o tebi","p-self.line":"Mod umora, podsjetnici na brigu o sebi i 4:20.","p-servers.name":"Serveri i rast","p-servers.line":"Globalne postavke servera, uloge i planiranje rasta.","p-livestream.name":"Dodaci za striming","p-livestream.line":"Twitch čet, vlastiti emotikoni i javni prikaz uživo."},"words":{"button":"📖 Programerske riječi","h":"📖 Objašnjene programerske riječi","intro":"Riječi koje koriste programeri (i AI timovi), običnim jezikom.","search":"Traži riječ…","none":"Nijedna riječ se ne poklapa.","close":"Zatvori","list":[{"id":"backlog","word":"Backlog","text":"Ideje i posao koji još nisu planirani. Na tome se ništa ne radi dok se ne premjesti u Za uraditi."},{"id":"sprint","word":"Sprint","text":"Kratak period rada (često sedmica ili dvije) s dogovorenim skupom kartica koje treba završiti.","also":["sprintovi","sprints"]},{"id":"standup","word":"Stand-up","text":"Brza provjera: šta je svaki član tima uradio, šta radi sljedeće i šta ga zaustavlja.","also":["standup","stand-upovi","stand-ups"]},{"id":"bug","word":"Bug","text":"Nešto što ne radi kako treba.","also":["bugovi","bugs"]},{"id":"test","word":"Test","text":"Isprobavanje završenog posla da se provjeri radi li ono što je traženo, prije nego što ga prihvatiš.","also":["testovi","tests"],"noTip":1},{"id":"commit","word":"Commit","text":"Sačuvan snimak koda, s kratkom bilješkom šta se promijenilo. Uvijek se možeš vratiti na njega.","also":["commitovi","commits"]},{"id":"push","word":"Push","text":"Slanje sačuvanih snimaka (commitova) s ovog računara na GitHub, da budu sigurnosno kopirani i podijeljeni."},{"id":"branch","word":"Branch","text":"Zasebna linija rada u kodu, da se mogu praviti promjene bez diranja glavne verzije.","also":["branchevi","branches"]},{"id":"merge","word":"Merge","text":"Spajanje promjena iz brancha nazad u glavnu verziju."},{"id":"repo","word":"Repo","text":"Folder projekta s kodom i cijelom historijom commitova, obično čuvan i na GitHubu.","also":["repozitorij","repository"]},{"id":"refactor","word":"Refaktorisanje","text":"Sređivanje koda bez mijenjanja onoga što radi: manje datoteke, jasnija imena, manje ponavljanja."},{"id":"deploy","word":"Deploy","text":"Puštanje nove verzije uživo, na primjer na server gdje je ljudi koriste."},{"id":"kanban","word":"Kanban","text":"Ploča s kolonama (Za uraditi, U toku, Gotovo) na kojoj se kartice kreću slijeva nadesno dok se radi."},{"id":"wip","word":"WIP limit","text":"Rad u toku: najviše kartica koje jedna kolona treba držati, da tim završava stvari prije nego što započne nove.","also":["WIP"]},{"id":"pr","word":"Pull request","text":"Traženje da se promjene brancha provjere i spoje u glavnu verziju.","also":["PR"]},{"id":"hook","word":"Hook","text":"Mala komanda koja se sama izvršava u određenom trenutku, npr. kad počne AI sesija, da tim čuje tvoje komentare.","also":["hookovi","hooks"]},{"id":"token","word":"Token","text":"Jedinica u kojoj se broji korištenje AI-ja: otprilike nekoliko slova teksta pročitanih ili napisanih. Manje tokena, više plana ostaje.","also":["tokeni","tokens"]},{"id":"agent","word":"Agent","text":"AI koji sam radi na zadatku: čita kod, pravi promjene, pokreće provjere i javlja rezultat.","also":["agenti","agents"]}]}};
